CREATE TABLE IF NOT EXISTS chinalife_voice_members(user_id INT UNSIGNED NOT NULL PRIMARY KEY,session VARCHAR(80) NOT NULL,city VARCHAR(80) NOT NULL,place VARCHAR(80) NOT NULL,muted TINYINT(1) NOT NULL DEFAULT 1,seen_at DATETIME NOT NULL,INDEX(city,place,seen_at),CONSTRAINT fk_chinalife_voice_user FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS chinalife_voice_signals(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,sender_id INT UNSIGNED NOT NULL,target_id INT UNSIGNED NOT NULL,city VARCHAR(80) NOT NULL,place VARCHAR(80) NOT NULL,target_session VARCHAR(80) NOT NULL,payload TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(target_id,target_session,id),CONSTRAINT fk_chinalife_voice_sender FOREIGN KEY(sender_id) REFERENCES users(user_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
